package io.github.diodeme.ji.ai;

/** Durable reference to credential material owned by a credential store. */
public record CredentialReference(String id, Type type) {
    public CredentialReference {
        if (id == null || id.isBlank()) throw new IllegalArgumentException("credential id must not be blank");
        if (type == null) throw new IllegalArgumentException("credential type must not be null");
    }

    public static CredentialReference none() {
        return new CredentialReference("none", Type.NONE);
    }

    public enum Type {
        NONE,
        API_KEY,
        BEARER_TOKEN,
        OAUTH,
        CLOUD,
        CUSTOM_SERVICE
    }
}
